import limited_client as robot,numpy as np
for c in ['topview','corner3']:
 o=robot.observe(c); a=o['rgb']; d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world'];
 m=(a[:,:,1]>180)&(a[:,:,0]<100)&(a[:,:,2]<120)
 y,x=np.where(m)
 print(c,'green',len(x),(x.min(),x.max(),y.min(),y.max()) if len(x) else None)
 for xx,yy in [(int(x.mean()),int(y.mean()))] if len(x) else []:
  dep=d[yy,xx]; q=np.array([(xx-240)*dep/K[0,0],(yy-240)*dep/K[1,1],dep,1]); print('centroid pix',xx,yy,'depth',dep,'world',T@q)
  for px,py in [(x.min(),y.min()),(x.max(),y.max()),(x.min(),y.max()),(x.max(),y.min())]:
   z=d[py,px]; print((px,py),z,(T@np.array([(px-240)*z/K[0,0],(py-240)*z/K[1,1],z,1]))[:3])
PY

